def f_real(n):
    x = Symbol('x')
    a = n*n - 8*n + 12
    return len(set(real_roots(x**n - a)))

def skill():
    tot = 0
    for n in range(2, 11):
        a = (n - 2)*(n - 6)
        if n % 2:
            tot += 1
        else:
            tot += 2 if a > 0 else (1 if a == 0 else 0)
    return tot

def standard():
    return sum(f_real(n) for n in range(2, 11))

def unique():
    return [standard()]
